evidence.source:
cd "C:/Users/cooll/AppData/Local/Temp/frontier-hard-005-hard-005-run-001-8f0888-bYgaWY" && node --input-type=module -e "
import { parse, stringify } from './src/index.ts';

// Test with astral ID_Continue character after param name
// U+10400 is DESERET CAPITAL LETTER LONG I, which is an ID_Continue character
// The input should be: :name followed by a text starting with astral ID_Continue char
const astralChar = '\u{10400}'; // 𐐀 - astral ID_Continue character
const path = ':name' + astralChar;
console.log('Input path:', JSON.stringify(path));
console.log('Astral char is ID_Continue:', /\p{ID_Continue}/u.test(astralChar));

try {
  const tokens = parse(path);
  console.log('Parsed tokens:', JSON.stringify(tokens.tokens));

  const result = stringify(tokens);
  console.log('Stringified:', JSON.stringify(result));
  console.log('Round-trip match:', result === path);

  // Try to re-parse the stringified result
  const tokens2 = parse(result);
  console.log('Re-parsed tokens:', JSON.stringify(tokens2.tokens));
} catch(e) {
  console.error('Error:', e.message);
}
"

